import {Battle,STAGES,REGIONS,BOSSES,HEROES,BUILDINGS,loadSave,persist,upgrade,upgradeCost,clamp,freshSave} from './engine.js?v=1.2';
import {SoftwareView} from './software.js?v=1.2';
const $=id=>document.getElementById(id);let storage;try{storage=localStorage;}catch{storage={getItem:()=>null,setItem:()=>{throw Error('Storage unavailable');}};}const save=loadSave(storage);let view,battle=new Battle(),screen='menu',paused=false,last=0,acc=0,activePage='campaign',selectedStage=save.unlocked,runMode='campaign',bannerUntil=0,toastUntil=0,result=null,autoPause=false;
const keys=new Set();let drag=null,saveFailed=false;
const audio={ctx:null,next:0,note:0,start(){if(!save.settings.sound)return;try{this.ctx||=new (window.AudioContext||window.webkitAudioContext)();this.ctx.resume().catch(()=>{});}catch{}},tone(freq,duration=.08,volume=.025,type='triangle',slide=0){const c=this.ctx;if(!c||c.state!=='running'||!save.settings.sound)return;const o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(freq,c.currentTime);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(20,slide),c.currentTime+duration);g.gain.setValueAtTime(volume,c.currentTime);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+duration);o.connect(g).connect(c.destination);o.start();o.stop(c.currentTime+duration);},update(){const c=this.ctx;if(!c||paused||!save.settings.sound||c.currentTime<this.next)return;this.next=c.currentTime+.43;const notes=[146.83,220,293.66,329.63,293.66,220,174.61,196];const f=notes[this.note++%notes.length];this.tone(f,1.4,.009,'sine');if(this.note%4===0)this.tone(f/2,2,.016,'sine');},event(type){if(type==='shoot')this.tone(700,.07,.012,'triangle',190);if(type==='impact')this.tone(120,.06,.015,'square',60);if(type==='hurt')this.tone(90,.2,.04,'sawtooth',35);if(type==='recruit'){this.tone(440,.18,.035);this.tone(659,.3,.02);}if(type==='ability'){this.tone(220,.5,.04,'sawtooth',880);}if(type==='victory'){[261,329,392,523].forEach((n,i)=>setTimeout(()=>this.tone(n,.8,.04),i*130));}if(type==='boss')this.tone(55,2,.05,'sawtooth',110);}};
function writeSave(){if(!persist(save,storage)&&!saveFailed){saveFailed=true;notify('Storage full: progress lasts this session');}}
function notify(text){$('toast').textContent=text;toastUntil=performance.now()+1600;}
function banner(text,sub='',duration=2500){$('banner').innerHTML=`${text}${sub?`<small>${sub}</small>`:''}`;bannerUntil=performance.now()+duration;}
function events(type,p={}){audio.event(type);if(['impact','destroy','hurt','recruit','ability','hazard'].includes(type))view?.effect(type,p);if(type==='recruit')notify('+'+p.amount+' TROOPS');if(type==='hurt')notify('−'+p.amount+' TROOPS');if(type==='weapon')notify('WEAPONS UPGRADED');if(type==='boss')banner(p.name,p.title,3500);if(type==='enrage')banner('The final stand','PHASE III · STAY CLEAR OF THE MARKED LANES',2200);if(type==='region')banner(REGIONS[Math.floor(p/2)].name,'THE MARCH CONTINUES');if(type==='victory'||type==='defeat'){setTimeout(()=>showResult(),type==='victory'?950:500);}}
async function setupRenderer(){try{if(new URLSearchParams(location.search).has('compat'))throw Error('Compatibility requested');const {View}=await import('./visuals.js?v=1.2');view=new View($('scene'),save.settings);}catch(error){const old=$('scene'),c=old.cloneNode();old.replaceWith(c);view=new SoftwareView(c,save.settings);$('rendererNote').hidden=false;$('rendererNote').textContent='Compatibility renderer · all gameplay available';}installCanvas();$('scene').addEventListener('webglcontextlost',e=>{e.preventDefault();paused=true;const old=$('scene'),c=old.cloneNode();old.replaceWith(c);view=new SoftwareView(c,save.settings);installCanvas();$('rendererNote').hidden=false;$('rendererNote').textContent='Graphics recovered in compatibility mode';if(screen==='battle')pauseDialog();});}
function updateMenu(){writeSave();$('gold').textContent=save.gold.toLocaleString();$('continueBtn').querySelector('span').textContent=save.cleared.length===12?'March again':'Begin the march';const level=1+Object.values(save.upgrades).reduce((a,b)=>a+b,0);$('realmLevel').textContent='KINGDOM LEVEL '+level;$('realmDesc').textContent=level>8?'A rising realm. A banner the world remembers.':'A small keep. The beginning of something greater.';renderPage(activePage);}
function head(title,desc,right=''){return `<div class="section-head"><div><h2>${title}</h2><p>${desc}</p></div><span>${right}</span></div>`;}
function renderPage(page){activePage=page;document.querySelectorAll('[data-page]').forEach(el=>el.classList.toggle('selected',el.dataset.page===page));const root=$('page');if(page==='campaign'){root.innerHTML=head('The road to the crown','Six realms. Twelve battles. One banner.',save.cleared.length+' / 12 CONQUERED')+'<div class="cards">'+STAGES.map((s,i)=>{const locked=i>save.unlocked,cleared=save.cleared.includes(i);return `<button class="stage-card ${locked?'locked':i===save.unlocked?'current':''}" style="--accent:${REGIONS[s.region].accent}" data-stage="${i}" ${locked?'disabled':''}><span class="number">${String(i+1).padStart(2,'0')}</span><small>${REGIONS[s.region].name}</small><strong>${s.name}</strong><span class="stage-state">${locked?'♙ LOCKED':cleared?'✓ RECLAIMED':s.boss!==null?'♛ TITAN ENCOUNTER':'⚔ MARCH TO BATTLE'}</span></button>`;}).join('')+'</div>';root.querySelectorAll('[data-stage]').forEach(el=>el.onclick=()=>brief(Number(el.dataset.stage),'campaign'));}
 if(page==='kingdom'){root.innerHTML=head('Build your legacy','Instant upgrades. Lasting strength. Earn gold on every march.','◈ '+save.gold+' GOLD')+'<div class="cards buildings">'+Object.entries(BUILDINGS).map(([k,v])=>`<article class="building"><div class="building-icon">${v.icon}</div><h3>${v.name}</h3><small>LEVEL ${save.upgrades[k]} / 10</small><p>${v.detail}</p><button class="upgrade-btn" data-upgrade="${k}" ${save.upgrades[k]>=10||save.gold<upgradeCost(save,k)?'disabled':''}>${save.upgrades[k]>=10?'Fully upgraded':'Upgrade · ◈ '+upgradeCost(save,k)}</button></article>`).join('')+'</div>';root.querySelectorAll('[data-upgrade]').forEach(el=>el.onclick=()=>{if(upgrade(save,el.dataset.upgrade)){audio.start();audio.event('recruit');updateMenu();}});}
 if(page==='heroes'){root.innerHTML=head('Those who carry the banner','Each hero changes your starting warband and ability strength.','HERO LEVEL '+(1+Math.floor(save.heroXP/180)))+'<div class="cards heroes">'+HEROES.map(h=>{const unlocked=save.unlocked>=h.unlock;return `<article class="hero-card ${save.hero===h.id?'active':''}"><div class="hero-avatar" style="background:${h.color};color:#294a50">${h.id==='sol'?'✧':h.id==='lyra'?'➶':h.id==='astrid'?'♞':'♜'}</div><h3>${h.name}</h3><small>${h.title}</small><p>${h.description}</p><button class="upgrade-btn" data-hero="${h.id}" ${!unlocked?'disabled':''}>${!unlocked?'Unlock after stage '+h.unlock:save.hero===h.id?'✓ Leading your army':'Select hero'}</button></article>`;}).join('')+'</div>';root.querySelectorAll('[data-hero]').forEach(el=>el.onclick=()=>{const h=HEROES.find(h=>h.id===el.dataset.hero);if(h&&h.unlock<=save.unlocked){save.hero=h.id;updateMenu();}});}
 if(page==='modes'){const modes=[['endless','∞','The endless march','An unbroken war across all six realms. Recruit, defeat titans, and see how far your banner travels.'],['bossrush','♛','The six sovereigns','Face all six titans in succession. Recover 15 soldiers after each fallen foe.'],['daily','✧','The daily banner','The same seeded battlefield for everyone. Standard hero and upgrades. A fresh challenge at midnight UTC.']];root.innerHTML=head('A different kind of glory','New ways to march. Always ready to play.')+'<div class="cards modes">'+modes.map(([id,symbol,title,desc])=>`<article class="mode-card"><div class="mode-symbol">${symbol}</div><h3>${title}</h3><p>${desc}</p><small>BEST ${save.best[id].toLocaleString()}${id==='daily'?' · '+new Date().toISOString().slice(0,10):''}</small><button class="upgrade-btn" data-mode="${id}">Raise the banner →</button></article>`).join('')+'</div>';root.querySelectorAll('[data-mode]').forEach(el=>el.onclick=()=>brief(el.dataset.mode==='daily'?5:0,el.dataset.mode));}}
function modal(html){$('modal').innerHTML='<section class="dialog">'+html+'</section>';$('modal').hidden=false;}
function closeModal(){$('modal').hidden=true;}
function brief(stage,mode){selectedStage=stage;runMode=mode;const s=STAGES[stage];modal(`<div class="eyebrow">${mode==='campaign'?'CHAPTER '+String(stage+1).padStart(2,'0'):mode==='daily'?'DAILY CHALLENGE':mode==='bossrush'?'BOSS RUSH':'ENDLESS MODE'} · ${REGIONS[s.region].name.toUpperCase()}</div><div class="medallion">${s.boss!==null?'♛':'⚑'}</div><h2>${mode==='bossrush'?'The six sovereigns':mode==='endless'?'The endless march':s.name}</h2><p>${mode==='bossrush'?'Dodge marked lanes. Align your army with glowing weak points.':s.brief}</p><ul class="onboarding"><li><b>↔ Steer</b> — Drag anywhere on the battlefield. On desktop use A/D or arrow keys.</li><li><b>➶ Fight</b> — Your troops shoot automatically. Break targets for recruits and weapon drops.</li><li><b>+ Choose wisely</b> — Walk through green gates to grow. Treasure and weapons may be worth a detour.</li><li><b>✧ Turn the tide</b> — Tap abilities below. Red floor markings mean an attack is coming.</li></ul><button class="primary" id="launch">⚔ &nbsp; Lead the warband</button><button class="secondary" id="backBrief">Back to kingdom</button>`);$('launch').onclick=()=>start(stage,mode);$('backBrief').onclick=closeModal;}
function start(stage=selectedStage,mode=runMode){selectedStage=stage;runMode=mode;audio.start();closeModal();screen='battle';paused=false;autoPause=false;result=null;battle=new Battle({stage,mode,save,event:events});$('header').hidden=true;$('menu').hidden=true;$('battleUI').hidden=false;document.body.classList.add('playing');$('steerHint').style.opacity=1;banner(STAGES[stage].name,REGIONS[Math.floor(stage/2)].name.toUpperCase());last=0;acc=0;keys.clear();}
function home(){if(screen==='battle'&&battle.status!=='playing'&&!battle.settled)battle.settle();screen='menu';paused=false;keys.clear();drag=null;closeModal();$('header').hidden=false;$('menu').hidden=false;$('battleUI').hidden=true;document.body.classList.remove('playing');updateMenu();}
function showResult(){if(screen!=='battle'||battle.status==='playing')return;result=battle.settle()||result;writeSave();const win=battle.status==='victory';const final=win&&selectedStage===11&&runMode==='campaign';modal(`<div class="eyebrow">${win?'THE BANNER STILL FLIES':'EVERY LEGEND HAS A SETBACK'}</div><div class="medallion">${win?'♛':'⚔'}</div><h2>${final?'A crown reclaimed.':win?'A glorious victory.':'Rise. Rally. Return.'}</h2><p>${final?'Emperor Veyr has fallen. Your kingdom is free. Endless battles and the six sovereigns await.':win?'Your soldiers return with spoils and stories. The next chapter awaits.':'Your treasury keeps the spoils you earned. Upgrade your kingdom and raise the banner again.'}</p><div class="result-stats"><div><b>+${result?.gold||0}</b><small>GOLD EARNED</small></div><div><b>${battle.kills}</b><small>FOES FALLEN</small></div><div><b>${battle.score}</b><small>SCORE</small></div></div>${win&&runMode==='campaign'&&selectedStage<11?'<button class="primary" id="nextStage">March to the next chapter →</button>':''}<button class="${win?'secondary':'primary'}" id="retryResult">${win?'Play again':'Rally the warband'}</button><button class="secondary" id="returnKingdom">Return to Havenhold</button>`);if($('nextStage'))$('nextStage').onclick=()=>brief(selectedStage+1,'campaign');$('retryResult').onclick=()=>start();$('returnKingdom').onclick=home;}
function pauseDialog(){if(screen!=='battle'||battle.status!=='playing')return;paused=true;keys.clear();modal('<div class="eyebrow">YOUR ARMY AWAITS</div><h2>A moment of peace.</h2><p>The march is paused.</p><button class="primary" id="resume">Resume the march</button><button class="secondary" id="restart">Restart battle</button><button class="secondary" id="pauseSettings">Settings</button><button class="secondary" id="leave">Return to kingdom</button>');$('resume').onclick=()=>{paused=false;autoPause=false;last=0;acc=0;closeModal();};$('restart').onclick=()=>start();$('leave').onclick=home;$('pauseSettings').onclick=settings;}
function settings(){const inBattle=screen==='battle';if(inBattle)paused=true;modal(`<div class="eyebrow">MAKE THE MARCH YOURS</div><h2>Settings</h2><div class="settings-row"><span>Battle audio</span><button class="secondary" id="toggleAudio" style="width:auto;margin:0">${save.settings.sound?'On':'Off'}</button></div><div class="settings-row"><span>Camera motion</span><button class="secondary" id="toggleMotion" style="width:auto;margin:0">${save.settings.motion?'On':'Reduced'}</button></div><div class="settings-row"><label for="difficulty">Battle difficulty</label><select id="difficulty"><option value="relaxed">Relaxed</option><option value="standard">Standard</option><option value="veteran">Veteran</option></select></div><div class="settings-row"><label for="quality">Graphics quality</label><select id="quality"><option value="auto">Adaptive</option><option value="high">High</option><option value="low">Battery saver</option></select></div><p>Difficulty applies to your next battle. Daily challenges always use Standard. Progress is saved on this device.</p><button class="primary" id="doneSettings">Done</button><button class="secondary" id="compatBtn">Use compatibility graphics</button>`);$('quality').value=save.settings.quality;$('difficulty').value=save.settings.difficulty;$('difficulty').onchange=()=>{save.settings.difficulty=$('difficulty').value;writeSave();};$('toggleAudio').onclick=()=>{save.settings.sound=!save.settings.sound;$('toggleAudio').textContent=save.settings.sound?'On':'Off';if(save.settings.sound)audio.start();writeSave();};$('toggleMotion').onclick=()=>{save.settings.motion=!save.settings.motion;document.body.classList.toggle('reduced',!save.settings.motion);$('toggleMotion').textContent=save.settings.motion?'On':'Reduced';writeSave();};$('quality').onchange=()=>{save.settings.quality=$('quality').value;view.quality(save.settings);writeSave();};$('doneSettings').onclick=()=>inBattle?pauseDialog():closeModal();$('compatBtn').onclick=()=>{const c=$('scene').cloneNode();$('scene').replaceWith(c);view.renderer?.dispose();view=new SoftwareView(c,save.settings);installCanvas();$('rendererNote').hidden=false;$('rendererNote').textContent='Compatibility renderer';inBattle?pauseDialog():closeModal();};}
function installCanvas(){const canvas=$('scene');canvas.addEventListener('pointerdown',e=>{if(screen!=='battle'||paused||battle.status!=='playing')return;drag={id:e.pointerId,x:e.clientX,target:battle.targetX};canvas.setPointerCapture(e.pointerId);audio.start();});canvas.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId||paused)return;battle.targetX=clamp(drag.target+(e.clientX-drag.x)/innerWidth*17,-6.2,6.2);});const release=()=>drag=null;canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);}
window.addEventListener('keydown',e=>{if(screen!=='battle'||battle.status!=='playing')return;if(['ArrowLeft','ArrowRight','a','d','A','D','1','2','3','4','Escape','p'].includes(e.key))e.preventDefault();if(e.key==='Escape'||e.key==='p'){if(paused&&$('resume'))$('resume').click();else pauseDialog();return;}if(!paused){keys.add(e.key.toLowerCase());const ability=['volley','shield','charge','magic'][Number(e.key)-1];if(ability)battle.ability(ability);}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{if(screen==='battle'&&!paused){autoPause=true;pauseDialog();}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&screen==='battle'&&!paused){autoPause=true;pauseDialog();}});window.addEventListener('resize',()=>view?.resize());
$('continueBtn').onclick=()=>brief(save.unlocked,'campaign');$('settingsBtn').onclick=settings;$('pauseBtn').onclick=pauseDialog;$('soundBtn').onclick=()=>{save.settings.sound=!save.settings.sound;if(save.settings.sound)audio.start();writeSave();};document.querySelector('.brand').onclick=e=>{e.preventDefault();home();};document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>renderPage(el.dataset.page));document.querySelectorAll('[data-ability]').forEach(el=>el.onclick=()=>{audio.start();if(!paused)battle.ability(el.dataset.ability);});
function frame(now){requestAnimationFrame(frame);const dt=last?Math.min((now-last)/1000,.1):1/60;last=now;if(screen==='battle'&&!paused){if(keys.has('a')||keys.has('arrowleft'))battle.targetX-=dt*9;if(keys.has('d')||keys.has('arrowright'))battle.targetX+=dt*9;battle.targetX=clamp(battle.targetX,-6.2,6.2);acc+=dt;while(acc>=1/60){battle.step(1/60);acc-=1/60;}}else acc=0;audio.update();view?.render(battle,paused?0:dt,screen);if(screen==='battle'){$('armyCount').textContent=battle.army;$('battleGold').textContent=battle.gold;$('regionName').textContent=REGIONS[Math.floor(battle.stage/2)].name.toUpperCase();$('stageName').textContent=STAGES[battle.stage].name;$('stageProgress').style.width=clamp(battle.distance/battle.config.length*100,0,100)+'%';$('soundBtn').textContent=save.settings.sound?'♪':'×';$('bossHUD').hidden=!battle.boss;if(battle.boss){$('bossName').textContent=battle.boss.name;$('bossPhase').textContent='PHASE '+['I','II','III'][battle.boss.phase-1];$('bossHealth').style.width=Math.max(0,battle.boss.hp/battle.boss.maxHp*100)+'%';$('bossHint').textContent=battle.boss.hint;}document.querySelectorAll('[data-ability]').forEach((el,i)=>{const remaining=battle.abilities[el.dataset.ability];el.classList.toggle('cooling',remaining>0);el.querySelector('small').textContent=remaining>0?Math.ceil(remaining)+'s':String(i+1);el.disabled=remaining>0||paused||battle.status!=='playing';});$('banner').style.opacity=now<bannerUntil?1:0;$('toast').style.opacity=now<toastUntil?1:0;if(battle.time>9)$('steerHint').style.opacity=0;}}
if(matchMedia('(prefers-reduced-motion: reduce)').matches)save.settings.motion=false;document.body.classList.toggle('reduced',!save.settings.motion);await setupRenderer();updateMenu();requestAnimationFrame(frame);
